/**
 * Inserts a whole import batch plus its replay record in one transaction, so
 * either every issue exists or none does. Numbers are consecutive from
 * `firstNumber`, in draft order.
 */
export async function insertIssueImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  authorId: UserId,
  firstNumber: number,
  drafts: readonly ImportedIssueDraft[],
): Promise<readonly Issue[]> {
  const db = getDb();
