    const created: Issue[] = [];
    drafts.forEach((draft, index) => {
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: firstNumber + index,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (draft.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            draft.labelIds.map((labelId) => ({
              orgId,
              issueId: row.id,
              labelId,
            })),
          )
          .run();
      }
      created.push(toIssue(row, draft.labelIds));
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey,
        projectId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return created;
  });
}
